// Some portions generated by Codex
package org.eclipse.rdf4j.federated.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Collections;
import java.util.Set;

import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF4J;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class GraphExecutionDatasetTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void selectedDefaultAliasPreservesResourceSelectorsAndMutationTargets() {
		Resource named = VF.createBNode("named");
		Resource removed = VF.createBNode("removed");
		Resource inserted = VF.createBNode("inserted");
		SimpleDataset original = new SimpleDataset();
		original.addNamedGraph(named);
		original.addDefaultRemoveGraph(removed);
		original.setDefaultInsertGraph(inserted);
		GraphExecutionDataset selected = new GraphExecutionDataset(original);

		assertEquals(Set.of(RDF4J.NIL), selected.getDefaultGraphResources());
		assertEquals(Set.of(named), selected.getNamedGraphResources());
		assertEquals(Set.of(removed), selected.getDefaultRemoveGraphResources());
		assertEquals(inserted, selected.getDefaultInsertGraphResource());
		assertThrows(IllegalStateException.class, selected::getNamedGraphs);
		assertThrows(IllegalStateException.class, selected::getDefaultRemoveGraphs);
		assertThrows(IllegalStateException.class, selected::getDefaultInsertGraph);

		original.removeNamedGraph(named);
		original.removeDefaultRemoveGraph(removed);
		original.setDefaultInsertGraph(VF.createIRI("urn:replacement"));
		assertEquals(Set.of(named), selected.getNamedGraphResources());
		assertEquals(Set.of(removed), selected.getDefaultRemoveGraphResources());
		assertEquals(inserted, selected.getDefaultInsertGraphResource());
		assertThrows(UnsupportedOperationException.class,
				() -> selected.getNamedGraphResources().clear());
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void readSelectionFlagIsAnIndependentSnapshot(boolean explicit) {
		SimpleDataset original = new SimpleDataset();
		original.setExplicitReadDataset(explicit);
		GraphExecutionDataset selected = new GraphExecutionDataset(original);
		original.setExplicitReadDataset(!explicit);

		assertEquals(explicit, selected.isExplicitReadDataset());
		assertEquals(Set.of(RDF4J.NIL), selected.getDefaultGraphs());
	}

	@Test
	void storeDefaultMutationTargetSurvivesTheGraphView() {
		SimpleDataset original = new SimpleDataset();
		original.addDefaultRemoveGraph((Resource) null);
		GraphExecutionDataset selected = new GraphExecutionDataset(original);

		assertEquals(Collections.singleton(null), selected.getDefaultRemoveGraphResources());
		assertEquals(Collections.singleton(null), selected.getDefaultRemoveGraphs());
	}
}
